/// The rule behind `build`, with the host's environment as input. Without `inherit` the start is empty, except
/// that Windows keeps the host's `SystemRoot` (contract §3: many programs cannot start without it). Each override
/// then replaces every variable of the same name, or removes it (`None`). Nothing is expanded.
pub(super) fn merge(
    host: impl IntoIterator<Item = (OsString, OsString)>,
    overrides: &[(OsString, Option<OsString>)],
    inherit: bool,
    os: Os,
) -> Vec<(OsString, OsString)> {
    let mut env: Vec<(OsString, OsString)> = match (inherit, os) {
        (true, _) => host.into_iter().collect(),
        (false, Os::Windows) => host
            .into_iter()
            .filter(|(name, _)| os.same_name(name, OsStr::new("SystemRoot")))
            .take(1)
            // The host may spell it `SYSTEMROOT` (an MSYS shell does); the child gets the usual spelling.
            .map(|(_, value)| (OsString::from("SystemRoot"), value))
            .collect(),
        (false, Os::Unix) => Vec::new(),
    };
    for (name, value) in overrides {
        env.retain(|(n, _)| !os.same_name(n, name));
        if let Some(value) = value {
            env.push((name.clone(), value.clone()));
        }
    }
    env

impl Os {
    /// Unix compares names exactly. Windows compares them by ordinal ignoring case over the whole UTF-16 sequence,
    /// like `CompareStringOrdinal(.., TRUE)`: unit against unit, each through `fold`.
    fn same_name(self, a: &OsStr, b: &OsStr) -> bool {
        match self {
            Os::Unix => a == b,
            Os::Windows => {
                let (a, b) = (utf16(a), utf16(b));
                a.len() == b.len() && a.iter().zip(&b).all(|(&x, &y)| fold(x) == fold(y))
            }
        }
    }
}

/// A UTF-16 unit through its simple upper case when it is a non-surrogate BMP character whose upper case is
/// exactly one BMP character; any other unit, surrogates included, unchanged (Windows' table works this way:
/// `ß` stays `ß`).
fn fold(unit: u16) -> u16 {
    let Some(c) = char::from_u32(u32::from(unit)) else {
        return unit;
    };
    let mut upper = c.to_uppercase();
    match (upper.next(), upper.next()) {
        (Some(u), None) => u16::try_from(u32::from(u)).unwrap_or(unit),
        _ => unit,
    }

/// Validates `req` per contract §3 (InvalidArgument / InvalidCwd), builds the final environment and resolves the program
/// against the child's final PATH (NotFound / NotExecutable). Never starts or executes anything.
pub(crate) fn prepare(req: &Request) -> Result<Spec, Error> {
    validate::check(req, HOST)?;
    let env = env::build(req);
    let cwd = validate::cwd(req)?;
    let program = resolve::program(&req.program, &env, &cwd)?;
    if req.verbatim.is_some() {
        validate::verbatim_program(&req.program, &program, HOST)?;
    }
    Ok(Spec {
        program,
        argv: std::iter::once(req.program.clone())
            .chain(req.args.iter().cloned())
            .collect(),
        env,
        cwd,
        mode: req.mode,
        stdin: req.stdin,
        merge_stderr: req.merge_stderr,
        grace: req.grace,
        verbatim: req.verbatim.clone(),
    })

/// `path` made absolute against the absolute directory `base`; `None` for a Windows drive-relative `path`.
pub(super) fn join(base: &Path, path: &OsStr, os: Os) -> Option<PathBuf> {
    match (os, kind(path, os)) {
        (Os::Unix, _) => Some(base.join(path)),
        (Os::Windows, Kind::DriveRelative) => None,
        (Os::Windows, Kind::Absolute) => Some(PathBuf::from(path)),
        (Os::Windows, Kind::RootRelative) => Some(match drive(base.as_os_str().as_encoded_bytes()) {
            Some(letter) => concat(&format!("{letter}:"), path),
            // A UNC or `\\?\` base: std's rule, which is Windows' own on the only host that has such bases.
            None => base.join(path),
        }),
        // A `\\?\` base takes no `/` and no `.`: std normalizes `path` into it.
        (Os::Windows, Kind::Relative) if is_verbatim(base) => Some(base.join(path)),
        (Os::Windows, Kind::Relative) => {
            let mut joined = base.as_os_str().to_os_string();
            if !joined.as_encoded_bytes().last().is_some_and(|&b| is_sep(b, os)) {
                joined.push("\\");
            }
            joined.push(path);
            Some(PathBuf::from(joined))
        }
    }

/// The directories of a PATH value, empty ones dropped: `:`-separated on Unix; `;`-separated on Windows, where
/// double quotes protect a `;` and are removed (std's rule).
pub(super) fn split_path(value: &OsStr, os: Os) -> Vec<PathBuf> {
    let (sep, quotes) = match os {
        Os::Unix => (b':', false),
        Os::Windows => (b';', true),
    };
    split_os(value, sep, quotes).into_iter().map(PathBuf::from).collect()
}

/// Windows: the extension of the last component (after its last `.`, which must not be its first byte).
pub(super) fn extension(path: &OsStr) -> Option<&[u8]> {
    let bytes = path.as_encoded_bytes();
    let name = match bytes.iter().rposition(|&b| is_sep(b, Os::Windows)) {
        Some(at) => bytes.get(at + 1..).unwrap_or_default(),
        None => bytes,
    };
    match name.iter().rposition(|&b| b == b'.') {
        None | Some(0) => None,
        Some(at) => name.get(at + 1..),
    }

/// `units` cut at every unquoted `sep`; quotes removed; empty pieces dropped.
fn split<T: Copy + PartialEq + From<u8>>(units: &[T], sep: u8, quotes: bool) -> Vec<Vec<T>> {
    let mut pieces = vec![Vec::new()];
    let mut quoted = false;
    for &unit in units {
        if quotes && unit == T::from(b'"') {
            quoted = !quoted;
        } else if !quoted && unit == T::from(sep) {
            pieces.push(Vec::new());
        } else if let Some(piece) = pieces.last_mut() {
            piece.push(unit);
        }
    }
    pieces.retain(|piece| !piece.is_empty());
    pieces

