/// Windows: the child's PATHEXT, lower-cased (as files are usually named). Elsewhere: none.
fn extensions(env: &[(OsString, OsString)], os: Os) -> Vec<String> {
    if os == Os::Unix {
        return Vec::new();
    }
    let parse = |list: &str| -> Vec<String> {
        list.split(';')
            .filter(|ext| !ext.is_empty())
            .map(str::to_ascii_lowercase)
            .collect()
    };
    let exts = env::get(env, "PATHEXT", os).map_or_else(Vec::new, |v| parse(&v.to_string_lossy()));
    if exts.is_empty() { parse(DEFAULT_PATHEXT) } else { exts }

/// Windows starts these without a shell (`.bat`/`.cmd` through `cmd.exe`, C-SPAWN-02); anything else is refused.
fn startable(path: &Path) -> bool {
    path::extension(path.as_os_str()).is_some_and(|ext| {
        [b"exe", b"com", b"bat", b"cmd"]
            .iter()
            .any(|s| ext.eq_ignore_ascii_case(*s))
    })

/// Whether the effective user may execute `path`, by the kernel's own rule: the owner needs the owner's execute
/// bit even when others have one; root needs any. `Ok(false)` is a refusal (`EACCES`); other errors come back as
/// they are.
///
/// Never `AT_EACCESS`: musl implements it, when the real and effective ids differ, by forking a helper process
/// (`src/unistd/faccessat.c`), and the host never forks (ADR-0005 §9). With equal ids (every normal host) the
/// plain `faccessat(X_OK, 0)` is the same check, and no libc forks for it. A setuid/setgid host skips the
/// host-side check: a regular file with any execute bit is accepted, and `execve` in the supervisor decides.
pub(super) fn can_execute(path: &Path) -> io::Result<bool> {
    if !same_ids() {
        let meta = std::fs::metadata(path)?;
        return Ok(meta.is_file() && meta.permissions().mode() & 0o111 != 0);
    }
    // Validation rejects NUL in every string a path is built from, so this fails only if that rule breaks.
    let path = CString::new(path.as_os_str().as_bytes()).map_err(|_| io::Error::from(io::ErrorKind::InvalidInput))?;
    // SAFETY: `path` is a valid NUL-terminated C string that lives across the call, and `faccessat` only reads it.
    // `AT_FDCWD` never matters: resolution makes every candidate absolute.
    let status = unsafe { libc::faccessat(libc::AT_FDCWD, path.as_ptr(), libc::X_OK, 0) };
    if status == 0 {
        return Ok(true);
    }
    let err = io::Error::last_os_error();
    if err.kind() == io::ErrorKind::PermissionDenied {
        Ok(false)
    } else {
        Err(err)
    }

#[test]
fn windows_names_ignore_case_over_the_whole_utf16_even_with_lone_surrogates() {
    let (upper, lower, other) = (wide(&[0xC4, 0xD800]), wide(&[0xE4, 0xD800]), wide(&[0xC4, 0xD801]));
    let host = vec![(upper, os("1")), (other.clone(), os("2"))];
    // "ÄD800" and "äD800" are one name; "ÄD801" is another.
    let replaced = merge(host.clone(), &[(lower.clone(), Some(os("x")))], true, Os::Windows);
    assert_eq!(replaced, [(other.clone(), os("2")), (lower.clone(), os("x"))]);
    let removed = merge(host, &[(lower, None)], true, Os::Windows);
    assert_eq!(removed, [(other, os("2"))]);
    // Only one-to-one BMP upper cases fold: ß stays ß, and 𐐨 (upper case 𐐀, outside the BMP) stays 𐐨.
    let kept = vars(&[("ß", "1"), ("𐐨", "2")]);
    assert_eq!(
        merge(kept.clone(), &[(os("SS"), None), (os("𐐀"), None)], true, Os::Windows),
        kept
    );

