/// A verbatim command line (amendment WP8b) never reaches a batch file: Windows would run it through `cmd.exe` with
/// the caller's tail unescaped, so the caller must name `cmd.exe` itself. `resolved` is the program as resolved; its
/// last component is compared the way Windows opens it (trailing dots and spaces dropped, any case).
pub(super) fn verbatim_program(command: &OsStr, resolved: &Path, os: Os) -> Result<(), Error> {
    let bytes = resolved.as_os_str().as_encoded_bytes();
    let name = match bytes.iter().rposition(|&b| path::is_sep(b, os)) {
        Some(at) => bytes.get(at + 1..).unwrap_or_default(),
        None => bytes,
    };
    let end = name
        .iter()
        .rposition(|&b| b != b'.' && b != b' ')
        .map_or(0, |last| last + 1);
    let name = name.get(..end).unwrap_or_default();
    let ext = name
        .len()
        .checked_sub(4)
        .and_then(|at| name.get(at..))
        .unwrap_or_default();
    if os == Os::Windows && (ext.eq_ignore_ascii_case(b".bat") || ext.eq_ignore_ascii_case(b".cmd")) {
        return Err(Error::verbatim_batch(command, resolved));
    }
    Ok(())

/// `dir` checked to be a directory (symlinks followed). `given` is the cwd as passed, for the message.
pub(super) fn directory(given: Option<&Path>, dir: PathBuf) -> Result<PathBuf, Error> {
    match std::fs::metadata(&dir) {
        Ok(meta) if meta.is_dir() => Ok(dir),
        Ok(_) => Err(Error::cwd_not_directory(given, &dir)),
        Err(err) if matches!(err.kind(), io::ErrorKind::NotFound | io::ErrorKind::NotADirectory) => {
            Err(Error::cwd_missing(given, &dir))
        }
        Err(err) => Err(Error::cwd_inaccessible(given, &dir, &err)),
    }
}

/// Byte offset of the first NUL (in the OS encoding: bytes on Unix, WTF-8 on Windows; NUL is one byte in both).
fn nul(s: &OsStr) -> Option<usize> {
    s.as_encoded_bytes().iter().position(|&b| b == 0)
}

fn cells(field: &str, value: u16) -> Result<(), Error> {
    if (1..=MAX_CELLS).contains(&value) {
        Ok(())
    } else {
        Err(Error::bad_pty_size(field, value))
    }
}

/// A fraction of a millisecond rounds up (contract §3).
fn millis(field: &str, value: Duration) -> Result<(), Error> {
    let ms = value.as_nanos().div_ceil(1_000_000);
    if ms <= MAX_MS {
        Ok(())
    } else {
        Err(Error::duration_out_of_range(field, ms))
    }

/// Output data: text with `text(true)` (the default), raw bytes with `text(false)`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Data {
    /// UTF-8 text, decoded across chunks; invalid bytes become U+FFFD.
    Text(String),
    /// Raw bytes, lossless.
    Bytes(Vec<u8>),
}

impl fmt::Display for Data {
    /// Text as is; bytes decoded lossily.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Data::Text(s) => f.write_str(s),
            Data::Bytes(b) => f.write_str(&String::from_utf8_lossy(b)),
        }

/// Why the root process ended (contract §7). The cause is committed when the library acts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Reason {
    /// It exited on its own.
    Exit,
    /// A signal ended it, not sent by this library (Unix only).
    Signal,
    /// `stop()` or dropping the child ended it.
    Killed,
    /// The timeout ended it.
    Timeout,
    /// Cancellation ended it.
    Aborted,
    /// The resident memory of the whole tree went over `max_rss_bytes`, and the tree was killed.
    MemoryExceeded,
}

/// How the root process ended.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct Exit {
    /// The exit code; `None` only when a Unix process was ended by a signal. Windows codes are reported as
    /// non-negative integers (e.g. `0xC000013A`).
    pub code: Option<u32>,
    /// The Unix signal name (e.g. `"SIGTERM"`); always `None` on Windows.
    pub signal: Option<String>,
    /// Why it ended.
    pub reason: Reason,
}

impl Exit {
    /// `reason` is `Exit` and the code is 0.
    pub fn success(&self) -> bool {
        self.reason == Reason::Exit && self.code == Some(0)
    }

